from rdkit import Chem
tests=[
 'Cc1cc(C)c([N-]([Zr])P(C(C)C)C(C)C)c(C)c1',
 'Cc1cc(C)c([N-]([Zr])P([Co])(C(C)C)C(C)C)c(C)c1',
