import math
from collections import Counter
atoms=[]
with open('constrained_xtb.xyz') as f:
    n=int(f.readline()); f.readline()
    for _ in range(n):
        s=f.readline().split(); atoms.append((s[0],tuple(map(float,s[1:4]))))
print(n, Counter(a for a,_ in atoms))
def d(i,j):
    return math.dist(atoms[i][1],atoms[j][1])
print('Zr-Co',d(0,59))
print('Zr-N aniline',d(0,1))
for i in [8,25,42]: print('Zr-N',i,d(0,i))
for i in [18,35,52]: print('Co-P',i,d(59,i))
print('Co-C',d(59,60),'C-N',d(60,61))
for n,p in [(8,18),(25,35),(42,52)]: print('N-P',n,p,d(n,p))
# shortest nonmetal contacts maybe? compute min interatomic distances excluding bonds? just overall min
mind=999; pair=None
for i in range(n):
    for j in range(i+1,n):
        dd=d(i,j)
        if dd<mind:
            mind=dd; pair=(i,j,atoms[i][0],atoms[j][0])
print('min contact',mind,pair)
